  ('f8802e6d-ed16-5652-a6fb-f70eb3e11b00', null, (select id from public.skills where slug = 'write-g9-narrative-writing'), null, 'easy',
   $q$Which sentence would best replace sentence 16 as a conclusion that reflects on the experience?$q$, $q$[{"text":"The art show had paintings, drawings, and photographs from every grade in the school.","is_correct":false,"misconception_token":"generic-fact-ending"},{"text":"After the show, I wrapped the bowl in newspaper and carried it home on the bus.","is_correct":false,"misconception_token":"flat-ending-no-reflection"},{"text":"I had spent three weeks working on the bowl before it went into the kiln.","is_correct":false,"misconception_token":"restates-situation"},{"text":"At the show, people stopped longest at my bowl, and I stopped wishing the crack away.","is_correct":true}]$q$::jsonb, $q$At the show, people stopped longest at my bowl, and I stopped wishing the crack away.$q$, $q$The correct choice shows how the narrator's feelings about the crack changed, which completes the story. Wrapping the bowl in newspaper is an action that offers no reflection.$q$, 'draft', '103a1107-a284-5605-bfbd-80966fd173e4')
