values
  ('a33edaa9-9db2-595d-b2fa-3d9123f666dc', null, (select id from public.skills where slug = 'write-g9-narrative-writing'), null, 'medium',
   $q$What is the main purpose of the word "Instead" at the beginning of sentence 12?$q$, $q$[{"text":"It shows that time has passed since the class opened the kiln.","is_correct":false,"misconception_token":"misreads-time-order"},{"text":"It shows that the crack was caused by the glaze the narrator chose.","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"It introduces a new character who helps the narrator fix the bowl.","is_correct":false,"misconception_token":"invents-character"},{"text":"It signals that the narrator chose a different reaction from the one described in sentence 11.","is_correct":true}]$q$::jsonb, $q$It signals that the narrator chose a different reaction from the one described in sentence 11.$q$, $q$"Instead" contrasts the urge to throw the bowl away in sentence 11 with the narrator looking at it more closely. The word marks a change in reaction, not a jump in time.$q$, 'draft', '103a1107-a284-5605-bfbd-80966fd173e4')
