values
  ('1ca2f4c7-b937-51c3-ab25-1e298af20e7c', null, (select id from public.skills where slug = 'write-g9-narrative-writing'), null, 'medium',
   $q$How do sentences 6 and 7 affect the pacing of the scene at the kiln?$q$, $q$[{"text":"They slow the story down by explaining how a kiln heats clay.","is_correct":false,"misconception_token":"misidentifies-content"},{"text":"They use dialogue to reveal how the other students felt about their work.","is_correct":false,"misconception_token":"no-dialogue-present"},{"text":"They speed the story up by skipping ahead to the day of the art show.","is_correct":false,"misconception_token":"misreads-pacing-speed"},{"text":"They build suspense by showing the other pieces first and then pausing on the narrator's bowl.","is_correct":true}]$q$::jsonb, $q$They build suspense by showing the other pieces first and then pausing on the narrator's bowl.$q$, $q$Handing out the other pieces one by one delays the moment the bowl appears, and the quiet room in sentence 7 makes readers wait for the reveal. The sentences contain no dialogue and no explanation of how a kiln works.$q$, 'draft', '103a1107-a284-5605-bfbd-80966fd173e4')
