  ('e082606d-f836-5135-8361-76c3cb3a558c', null, (select id from public.skills where slug = 'write-g9-sentence-structure'), null, 'medium',
   $q$Which sentence about the earthquake sensors is correctly written?$q$, $q$[{"text":"The sensors detected a small tremor. Because it was so faint that no one in town felt it.","is_correct":false,"misconception_token":"fragment-created"},{"text":"The sensors detected a small tremor, no one in town felt it because it was so faint.","is_correct":false,"misconception_token":"comma-splice"},{"text":"The sensors detected a small tremor, but no one in town felt it because it was so faint.","is_correct":true},{"text":"The sensors detected a small tremor, but no one in town felt it, it was so faint.","is_correct":false,"misconception_token":"comma-splice-second-clause"}]$q$::jsonb, $q$The sensors detected a small tremor, but no one in town felt it because it was so faint.$q$, $q$The correct sentence joins the first two clauses with ", but" and attaches the "because" clause directly. The choice ending "no one in town felt it, it was so faint" fixes the first boundary but then joins "it was so faint" with only a comma, creating a new splice.$q$, 'draft', null)
