  ('d4920e20-0b21-5f62-bd35-dcfc94cb44d5', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'medium',
   $q$Read the sentence: "Students can either submit the lab report online or they can hand it in at the front office." Which revision corrects the faulty parallel structure?$q$, $q$[{"text":"Students either can submit the lab report online or hand it in at the front office.","is_correct":false,"misconception_token":"misplaced-correlative"},{"text":"Students can either submit the lab report online, or they hand it in at the front office.","is_correct":false,"misconception_token":"clause-breaks-parallel"},{"text":"Students can either submit the lab report online or hand it in at the front office.","is_correct":true},{"text":"Students can submit either the lab report online or hand it in at the front office.","is_correct":false,"misconception_token":"misplaced-correlative"}]$q$::jsonb, $q$Students can either submit the lab report online or hand it in at the front office.$q$, $q$"Either" and "or" are each followed by a verb phrase ("submit the lab report online" and "hand it in at the front office"), so the two halves match. In the other revisions, "either" sits before a different kind of word than "or" does, or the second half is a full clause.$q$, 'draft', null)
